import React, { useState, useEffect } from "react";
import { collection, onSnapshot, query, where, deleteDoc, doc } from "firebase/firestore";
import { db } from "../firebase/config";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { FaUserCircle, FaPlus, FaTrash, FaPen, FaSearch, FaFilter } from "react-icons/fa";
import "../pages/adopter/AdopterDashboard.css";

const HomePage = () => {
    const navigate = useNavigate();
    const { user, logout } = useAuth();

    // UI States
    const [showMenu, setShowMenu] = useState(false);
    const [pets, setPets] = useState([]);
    const [loading, setLoading] = useState(true);

    // Filters
    const [search, setSearch] = useState("");
    const [filters, setFilters] = useState({ type: "" });

    // 1. LOGOUT
    const handleLogout = async () => {
        try {
            await logout();
            navigate("/login");
        } catch (error) {
            console.error("Logout failed:", error);
        }
    };

    // 2. READ DATA
    useEffect(() => {
        const q = query(collection(db, "pets"), where("adopted", "==", false));
        const unsubscribe = onSnapshot(q, (snapshot) => {
            const petsData = snapshot.docs.map((doc) => ({
                id: doc.id,
                ...doc.data(),
            }));
            setPets(petsData);
            setLoading(false);
        });
        return () => unsubscribe();
    }, []);

    // 3. DELETE PET
    const handleDelete = async (e, petId) => {
        e.stopPropagation();
        if (window.confirm("Are you sure? This will remove the listing permanently.")) {
            try {
                await deleteDoc(doc(db, "pets", petId));
            } catch (err) {
                console.error("Error deleting:", err);
            }
        }
    };

    const handleEdit = (e, petId) => {
        e.stopPropagation();
        navigate(`/edit-pet/${petId}`);
    };

    // 4. IMPROVED SEARCH & FILTER LOGIC
    const filteredPets = pets.filter((pet) => {
        const term = search.toLowerCase();

        // Safety checks in case fields are missing in database
        const pName = pet.name ? pet.name.toLowerCase() : "";
        const pBreed = pet.breed ? pet.breed.toLowerCase() : "";
        const pType = pet.type ? pet.type.toLowerCase() : "";

        // NOW SEARCHES BY NAME, BREED, OR TYPE
        const matchSearch =
            pName.includes(term) ||
            pBreed.includes(term) ||
            pType.includes(term);

        const matchType = filters.type
            ? pType === filters.type.toLowerCase()
            : true;

        return matchSearch && matchType;
    });

    return (
        <div className="adopter-container">
            {/* --- HEADER --- */}
            <header className="dashboard-header">
                <div className="header-left">
                    <h1 className="title">🐾 PetPal</h1>
                    <p className="subtitle">Find your new best friend.</p>
                </div>

                <div className="header-right" style={{ display:'flex', gap:'15px', alignItems:'center' }}>
                    <button
                        className="add-pet-btn-modern"
                        onClick={() => navigate("/add-pet")}
                    >
                        <FaPlus /> List a Pet
                    </button>

                    <div style={{ position: 'relative' }}>
                        <FaUserCircle
                            className="profile-icon"
                            onClick={() => setShowMenu(!showMenu)}
                        />
                        {showMenu && (
                            <div className="profile-dropdown">
                                <p style={{ fontSize: '0.9rem', paddingBottom:'10px', color:'#666' }}>{user?.email}</p>
                                <hr />
                                <button onClick={handleLogout}>Log Out</button>
                            </div>
                        )}
                    </div>
                </div>
            </header>

            {/* --- MODERN SEARCH & FILTERS BAR --- */}
            <div className="controls-wrapper">

                {/* Search Bar */}
                <div className="search-box">
                    <FaSearch className="search-icon" />
                    <input
                        type="text"
                        placeholder="Search by name, breed, or animal (e.g. 'Rabbit')..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                    />
                </div>

                {/* Filter Dropdown */}
                <div className="filter-box">
                    <FaFilter className="filter-icon" />
                    <select
                        value={filters.type}
                        onChange={(e) => setFilters({ ...filters, type: e.target.value })}
                    >
                        <option value="">All Animals</option>
                        <option value="Dog">Dogs 🐕</option>
                        <option value="Cat">Cats 🐈</option>
                        <option value="Rabbit">Rabbits qh</option>
                        <option value="Hamster">Hamsters 🐹</option>
                        <option value="Bird">Birds 🦜</option>
                        <option value="Fish">Fish 🐠</option>
                        <option value="Turtle">Turtles 🐢</option>
                        <option value="Other">Others ✨</option>
                    </select>
                </div>
            </div>

            {/* --- GRID --- */}
            <h2 className="section-title">
                {search || filters.type ? 'Search Results' : 'Recently Listed'}
                <span style={{ fontSize:'0.6em', color:'#888', marginLeft:'10px' }}>
                    ({filteredPets.length} found)
                </span>
            </h2>

            {loading ? <p>Loading...</p> : (
                <div className="cards-container">
                    {filteredPets.map((pet) => {
                        const isOwner = user && pet.ownerId === user.uid;

                        return (
                            <div
                                key={pet.id}
                                className="pet-card"
                                onClick={() => navigate(`/pet/${pet.id}`)}
                            >
                                {isOwner && <div className="owner-badge">MY LISTING</div>}

                                <div className="image-wrapper">
                                    <img
                                        src={pet.image}
                                        alt={pet.name}
                                        onError={(e) => {e.target.src = 'https://via.placeholder.com/300?text=No+Image'}}
                                    />
                                </div>

                                <div className="pet-info">
                                    <div className="pet-header">
                                        <h3>{pet.name}</h3>
                                        <span className="pet-breed-pill">{pet.type}</span>
                                    </div>
                                    <p className="pet-subtext">{pet.breed} • {pet.age}</p>

                                    {isOwner ? (
                                        <div className="action-buttons">
                                            <button
                                                className="edit-btn"
                                                onClick={(e) => handleEdit(e, pet.id)}>
                                                <FaPen />
                                            </button>
                                            <button
                                                className="delete-btn"
                                                onClick={(e) => handleDelete(e, pet.id)}>
                                                <FaTrash />
                                            </button>
                                        </div>
                                    ) : (
                                        <button className="details-btn">Meet {pet.name}</button>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
    );
};

export default HomePage;
